cd /Users/honlnk/project/short-drama-web
AWK='
  FNR==1 { files++ }
  { total++ }
  /^[[:space:]]*$/ { blank++; next }
  /^[[:space:]]*(\/\/|\/\*|\*|<!--|#)/ { comment++ }
  END { printf "文件:%d  总行:%d  空行:%d  注释:%d  有效代码:%d\n", files, total, blank, comment, total-blank-comment }
'
echo "== Java 主代码 =="; find apps/api/src/main -name "*.java" -print0 | xargs -0 awk "$AWK"
echo "== Java 测试 =="; find apps/api/src/test -name "*.java" -print0 | xargs -0 awk "$AWK"
echo "== C端 web src =="; find apps/web/src \( -name "*.ts" -o -name "*.tsx" -o -name "*.css" \) -print0 | xargs -0 awk "$AWK"
echo "== admin src =="; find apps/admin/src \( -name "*.ts" -o -name "*.tsx" -o -name "*.css" \) -print0 | xargs -0 awk "$AWK"
echo "== Shell 脚本 =="; find scripts -name "*.sh" -print0 | xargs -0 awk "$AWK"
echo "== 后端配置 yml+xml =="; printf '%s\0' apps/api/src/main/resources/application.yml apps/api/pom.xml | xargs -0 awk "$AWK"
echo "== 前端工程配置+html =="; find apps/web apps/admin -maxdepth 2 \( -name "vite.config.ts" -o -name "tsconfig*.json" -o -name "index.html" \) -not -path "*/node_modules/*" -print0 | xargs -0 awk "$AWK"
